// チェッカー
function setup() {
  createCanvas(200, 200);
  const size = width / 8; // マスの一辺の長さ

  for(let i = 0; i < 8; i++){
    for(let j = 0; j < 8; j++){
      // BLANK[1] ヒント： rectのx座標は 
      //size * i, y座標は size * j
      if((i + j) % 2 == 0){
        fill(255);
      }
      else{
        fill(125);
       stroke(125);
      }
    rect(size * i,size * j,size,size);

           if((i + j)%2==1 && (j<3)){
            fill(255,0,0)
        
            ellipse(size * (i + 0.5),size * (j + 0.5),size * 0.8,size * 0.8)
    }
    else if ((j>4)&&((i+j)%2==1)){
      fill(0,0,0)
      ellipse(size*(i+0.5),size*(j+0.5),size*0.8,size*0.8)
    }
    }
  }
}

// 神戸市のマーク
function setup(){
  createCanvas(96,96);
  background(255);

  noFill();
  strokeWeight(25);
  strokeCap(SQUARE);
  arc(100 + 25, 100, 100, 100, QUARTER_PI * 3, QUARTER_PI * 3 + PI);
  // BLANK[1] 空欄を埋めて神戸市のロゴマークを完成させよう
}

