  beginShape();
  for(let i = 0; i < 10; i++){
    const theta = TWO_PI * i / 10 - HALF_PI;
    let d;
    if(i % 2 == 0){ d = r; }      // 偶数番目は外側(とがった先)
    else { d = r / 2; }           // 奇数番目は内側(くぼみ)
    vertex(cx + cos(theta) * d, cy + sin(theta) * d);
  }
  endShape(CLOSE);
